import type {HandoffScope} from './cashier-handoff';
type Entry={deposit_id:string;deposit_journal_id:string;posting_date:string;transit_account_id:string;deposited_minor:string;outstanding_minor:string;requires_review:boolean};
export function readBankTransit(value:unknown,scope:HandoffScope,bank:string,end:string){if(!value||typeof value!=='object')throw Error('Invalid transit report.');const r=value as Record<string,unknown>;if(r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.bank_id!==bank||r.end_date_exclusive!==end||r.currency!=='USD'||r.basis!=='posted_deposits_less_posted_settlements'||r.bank_verified!==false||!Array.isArray(r.entries)||r.entries.length>10000||typeof r.outstanding_minor!=='string'||! /^-?\d+$/.test(r.outstanding_minor))throw Error('Transit report does not match this property and date.');let total=BigInt(0);const seen=new Set<string>();const entries:Entry[]=r.entries.map(v=>{if(!v||typeof v!=='object')throw Error('Invalid transit entry.');const e=v as Entry;for(const id of [e.deposit_id,e.deposit_journal_id,e.transit_account_id])if(typeof id!=='string'||! /^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$/i.test(id))throw Error('Invalid deposit reference.');if(seen.has(e.deposit_id)||typeof e.posting_date!=='string'||!/^\d{4}-\d{2}-\d{2}$/.test(e.posting_date)||e.posting_date>=end||typeof e.deposited_minor!=='string'||!/^\d+$/.test(e.deposited_minor)||typeof e.outstanding_minor!=='string'||! /^-?\d+$/.test(e.outstanding_minor)||BigInt(e.outstanding_minor)===BigInt(0)||BigInt(e.outstanding_minor)>BigInt(e.deposited_minor)||e.requires_review!==(BigInt(e.outstanding_minor)<BigInt(0)))throw Error('Invalid outstanding deposit amount.');seen.add(e.deposit_id);total+=BigInt(e.outstanding_minor);return e;});if(total!==BigInt(r.outstanding_minor))throw Error('Transit total does not match its deposits.');return {entries,total:r.outstanding_minor};}
